def solve(a,gap_tolerant=False):
    a=np.array(a); h,w=a.shape
    cnt=Counter(int(v) for v in a.flatten()); bg=cnt.most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    stack=[(0,0)]
    seen=set(); seen.add((0,0))
    # boundary walk: find all border-bag cells
    def push(i,j):
        if (i,j) not in seen: seen.add((i,j)); stack.append((i,j))
    for i in range(h): push(i,0); push(i,w-1)
    for j in range(w): push(0,j); push(h-1,j)
    while stack:
        i,j=stack.pop()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if not (0<=ni<h and 0<=nj<w): continue
            if (ni,nj) in seen: continue
            ok = a[ni,nj]==bg
            if not ok and gap_tolerant:
                r,c=ni,nj
                # count run-length of contiguous bg in row/col passing through (r,c) containing (ni,nj)
                # simpler: allow if either neighbor bg -> will be pushed anyway if other neighbor bg too... 
                # use: cell is bg-connected if it touches another reachable bg orthogonally
                nb_bg = (ni-1>=0 and a[ni-1,nj]==bg) or (ni+1<h and a[ni+1,nj]==bg) or (nj-1>=0 and a[ni,nj-1]==bg) or (nj+1<w and a[ni,nj+1]==bg)
                if not nb_bg: continue
            if not ok and gap_tolerant and not nb_bg: continue
            push(ni,nj)
    for i in range(h):
        for j in range(w):
            if a[i,j]==bg and (i,j) not in seen: out[i][j]=2
    return out
