from collections import Counter,deque
def enclosed_fill(a,fill=2):
    a=np.array(a); h,w=a.shape
    cnt=Counter(int(v) for v in a.flatten()); bg=cnt.most_common(1)[0][0]
    s=[v for v in cnt if v!=bg][0]
    out=a.copy()
    # flood fill bg from border through non-shape bg
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for r in range(h):
        for c in [0,w-1]:
            if out[r,c]==bg and not seen[r][c]:
                seen[r][c]=True; q.append((r,c))
    for c in range(w):
        for r in [0,h-1]:
            if out[r,c]==bg and not seen[r][c]:
                seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and out[nr,nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True; q.append((nr,nc))
    enclosed=[(r,c) for r in range(h) for c in range(w) if not seen[r][c]]
    # exclude small isolated bg regions (<3 cells) that might not be "enclosed" by shape segments
    from collections import Counter
    lab=[-1]*h
