def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(a):
    a=np.array(a); h,w=a.shape
    cnt=Counter(a.flatten()); bg=cnt.most_common(1)[0][0]; s=[v for v in cnt if v!=bg][0]
    out=a.copy(); reach=np.zeros((h,w),bool)
    q=deque([(r,c) for r in [0,h-1] for c in range(w)]+[(r,c) for r in range(h) for c in [0,w-1]])
    while q:
        y,x=q.popleft()
        for dy in (-1,0,1):
            for dx in (-1,0,1):
                yy,xx=y+dy,x+dx
                if 0<=yy<h and 0<=xx<w and a[yy,xx]==bg and not reach[yy,xx]:
                    reach[yy,xx]=True; q.append((yy,xx))
    return out,reach
for n in [2,3,4,5,6,7,8]:
    i=np.array(G[f'Demo pair {n} input']); b=np.array(G[f'Demo pair {n} output'])
    out,_=f(i)
    exp={(r,c) for r in range(b.shape[0]) for c in range(b.shape[1]) if b[r,c]!=i[r,c]}
    out_exp={k for k,v in {'out':list(out.flat)}.items()}
    pred_fill={(r,c) for r in range(out.shape[0]) for c in range(out.shape[1]) if out[r,c]==2}
    # extra/missing vs expected
    print(n,'extra:',sorted((r,c) for (r,c) in pred_fill-exp)[:6],'miss:',sorted((r,c) for (r,c) in exp-pred_fill)[:6])

